use std::collections::BTreeSet;

use anyhow::{Context, Result};
use proc_macro2::{Ident, Literal, TokenStream};
use quote::{format_ident, quote};

use crate::model::{EnumModel, Model, OptionModel, TypeKind, rust_ident};

const BUILD_HEADER: &str =
    "//! Generated by `cargo xtask generate-options` from `options.toml`. Do not edit.\n\n";

pub(crate) fn render_core(model: &Model) -> Result<String> {
    let enum_defs = model.enums.iter().map(render_enum);
    let fields = model.options.iter().map(render_option_field);
    let partial_fields = model.options.iter().map(render_partial_field);
    let default_fields = model.options.iter().map(|option| {
        let field = rust_ident(&option.name);
        let default = &option.default_expr;
        quote!(#field: #default)
    });
    let none_fields = model.options.iter().map(|option| {
        let field = rust_ident(&option.name);
        quote!(#field: None)
    });
    let merge_fields = model.options.iter().map(|option| {
        let field = rust_ident(&option.name);
        quote!(#field: newer.#field.or(self.#field))
    });
    let apply_fields = model.options.iter().map(|option| {
        let field = rust_ident(&option.name);
        quote! {
            if let Some(value) = overrides.#field {
                this.#field = value;
            }
        }
    });
    let specs = model
        .options
        .iter()
        .map(|option| render_option_spec(option, model));
    let option_enums = model.enums.iter().map(render_option_enum);

    let tokens = quote! {
        #(#enum_defs)*

        /// Configuration options for the Typstyle printer.
        #[derive(Debug, Clone, PartialEq, Eq, Hash)]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        #[cfg_attr(feature = "serde", serde(default))]
        pub struct Options {
            #(#fields)*
        }

        /// Explicit overrides for [`Options`].
        #[derive(Debug, Clone, PartialEq, Eq, Hash)]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        #[cfg_attr(feature = "serde", serde(default, deny_unknown_fields))]
        pub struct PartialOptions {
            #(#partial_fields)*
        }

        impl Default for Options {
            fn default() -> Self {
                Self {
                    #(#default_fields),*
                }
            }
        }

        impl Default for PartialOptions {
            fn default() -> Self {
                Self {
                    #(#none_fields),*
                }
            }
        }

        impl PartialOptions {
            /// Combines overrides, with `newer` taking precedence over `self`.
            pub fn merge(self, newer: Self) -> Self {
                Self {
                    #(#merge_fields),*
                }
            }

            /// Resolves these overrides against the built-in defaults.
            pub fn resolve(self) -> Result<Options, crate::option::OptionsError> {
                Options::default().apply(self)
            }
        }

        impl Options {
            /// Option metadata in declaration order, used to generate bindings and docs.
            pub const OPTION_SPECS: &'static [crate::option::OptionSpec] = &[
                #(#specs),*
            ];

            /// Applies explicit overrides and validates the result.
            pub fn apply(
                self,
                overrides: PartialOptions,
            ) -> Result<Self, crate::option::OptionsError> {
                let mut this = self;
                #(#apply_fields)*
                this.validate()?;
                Ok(this)
            }
        }

        #(#option_enums)*
    };

    format_rust(tokens)
}

fn render_enum(enum_model: &EnumModel) -> TokenStream {
    let name = rust_ident(&enum_model.name);
    let doc = doc_attrs(&enum_model.description);
    let variants = enum_model.variants.iter().map(|variant| {
        let variant_name = rust_ident(&variant.name);
        let variant_doc = doc_attrs(&variant.description);
        let value = &variant.value;
        let default = if variant.value == enum_model.default {
            quote!(#[default])
        } else {
            TokenStream::new()
        };
        quote! {
            #variant_doc
            #default
            #[cfg_attr(feature = "serde", serde(rename = #value))]
            #variant_name,
        }
    });

    quote! {
        #doc
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
        #[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
        pub enum #name {
            #(#variants)*
        }
    }
}

fn render_option_field(option: &OptionModel) -> TokenStream {
    let name = rust_ident(&option.name);
    let ty = option.type_tokens();
    let doc = doc_attrs(&option.description);
    quote! {
        #doc
        pub #name: #ty,
    }
}

fn render_partial_field(option: &OptionModel) -> TokenStream {
    let name = rust_ident(&option.name);
    let ty = option.type_tokens();
    let doc = doc_attrs(&option.description);
    quote! {
        #doc
        #[cfg_attr(feature = "serde", serde(skip_serializing_if = "Option::is_none"))]
        pub #name: Option<#ty>,
    }
}

fn render_option_spec(option: &OptionModel, model: &Model) -> TokenStream {
    let key = &option.name;
    let label = &option.label;
    let description = option.description.trim();
    let kind = spec_kind(option.kind);
    let choices = match option.kind {
        TypeKind::Enum(_) => {
            let values = option
                .choices(model)
                .iter()
                .map(|variant| &variant.value)
                .collect::<Vec<_>>();
            quote!(&[#(#values),*])
        }
        _ => quote!(&[]),
    };
    let group = &option.group;
    let widget = &option.widget;
    let type_name = match option.kind {
        TypeKind::Enum(index) => model.enum_model(index).name.clone(),
        _ => String::new(),
    };
    let order = Literal::usize_unsuffixed(option.order);

    quote! {
        crate::option::OptionSpec {
            key: #key,
            label: #label,
            description: #description,
            kind: #kind,
            choices: #choices,
            group: #group,
            widget: Some(#widget),
            type_name: #type_name,
            order: #order,
        }
    }
}

fn render_option_enum(enum_model: &EnumModel) -> TokenStream {
    let name = rust_ident(&enum_model.name);
    let values = enum_model
        .variants
        .iter()
        .map(|variant| &variant.value)
        .collect::<Vec<_>>();
    let arms = enum_model.variants.iter().map(|variant| {
        let value = &variant.value;
        let name = rust_ident(&variant.name);
        quote!(#value => Some(Self::#name),)
    });
    quote! {
        impl crate::option::OptionEnum for #name {
            const CHOICES: &'static [&'static str] = &[#(#values),*];

            fn from_choice(value: &str) -> Option<Self> {
                match value {
                    #(#arms)*
                    _ => None,
                }
            }
        }
    }
}

fn spec_kind(kind: TypeKind) -> TokenStream {
    match kind {
        TypeKind::Boolean => quote!(crate::option::OptionKind::Boolean),
        TypeKind::Integer => quote!(crate::option::OptionKind::Integer),
        TypeKind::Float => quote!(crate::option::OptionKind::Float),
        TypeKind::String => quote!(crate::option::OptionKind::String),
        TypeKind::Enum(_) => quote!(crate::option::OptionKind::Enum),
    }
}

pub(crate) fn render_cli(model: &Model) -> Result<String> {
    let fields = model
        .options
        .iter()
        .map(|option| render_arg_field(option, model));
    let inverse_fields = model.options.iter().filter_map(render_inverse_field);
    let field_inits = model.options.iter().map(|option| {
        let field = rust_ident(&option.name);
        let value = match option.kind {
            TypeKind::String => quote!(args.#field.clone()),
            _ => quote!(args.#field),
        };
        quote!(#field: #value)
    });
    let inverse_inits = model.options.iter().filter_map(|option| {
        option.cli.inverse.as_ref().map(|inverse| {
            let field = rust_ident(&option.name);
            let inverse_field = &inverse.field;
            quote! {
                if args.#inverse_field {
                    partial.#field = Some(false);
                }
            }
        })
    });

    let mut used_enums = BTreeSet::new();
    for option in &model.options {
        if let TypeKind::Enum(index) = option.kind {
            used_enums.insert(index);
        }
    }
    let parsers = used_enums
        .into_iter()
        .map(|index| render_value_parser(model.enum_model(index)));

    let tokens = quote! {
        use typstyle_core::PartialOptions;

        /// Formatter options exposed by the command line.
        #[derive(Debug, Clone, clap::Args)]
        pub struct OptionArgs {
            #(#fields)*
            #(#inverse_fields)*
        }

        impl OptionArgs {
            /// Converts CLI options into explicit formatter overrides.
            pub fn to_partial(&self) -> PartialOptions {
                self.into()
            }
        }

        impl From<&OptionArgs> for PartialOptions {
            fn from(args: &OptionArgs) -> Self {
                let mut partial = PartialOptions {
                    #(#field_inits),*
                };
                #(#inverse_inits)*
                partial
            }
        }

        impl From<OptionArgs> for PartialOptions {
            fn from(args: OptionArgs) -> Self {
                (&args).into()
            }
        }

        #(#parsers)*
    };

    format_rust(tokens)
}

fn render_arg_field(option: &OptionModel, model: &Model) -> TokenStream {
    let field = rust_ident(&option.name);
    let ty = option.cli_type_tokens(model);
    let attr = render_arg_attr(option, model);
    quote! {
        #attr
        #field: Option<#ty>,
    }
}

fn render_arg_attr(option: &OptionModel, model: &Model) -> TokenStream {
    let mut attrs = Vec::new();
    if let Some(short) = option.cli.short {
        let short = Literal::character(short);
        attrs.push(quote!(short = #short));
    }
    let long = &option.cli.long;
    attrs.push(quote!(long = #long));
    if let Some(alias) = &option.cli.visible_alias {
        attrs.push(quote!(visible_alias = #alias));
    }
    if let Some(short) = option.cli.visible_short_alias {
        let short = Literal::character(short);
        attrs.push(quote!(visible_short_alias = #short));
    }
    if let Some(value_name) = &option.cli.value_name {
        attrs.push(quote!(value_name = #value_name));
    }
    attrs.push(quote!(global = true));
    let help = option.help();
    attrs.push(quote!(help = #help));
    if let TypeKind::Enum(index) = option.kind {
        let parser = value_parser_name(model.enum_model(index));
        attrs.push(quote!(value_parser = #parser()));
    }
    if let Some(value) = &option.cli.implicit_value {
        attrs.push(quote! {
            num_args = 0..=1,
            default_missing_value = #value,
            require_equals = true
        });
    }
    quote! {
        #[arg(#(#attrs),*)]
    }
}

fn render_inverse_field(option: &OptionModel) -> Option<TokenStream> {
    let inverse = option.cli.inverse.as_ref()?;
    let field = &inverse.field;
    let long = &inverse.long;
    let description = &inverse.description;
    let conflicts = &option.name;
    Some(quote! {
        #[arg(
            long = #long,
            default_value_t = false,
            global = true,
            conflicts_with = #conflicts,
            help = #description
        )]
        #field: bool,
    })
}

fn render_value_parser(enum_model: &EnumModel) -> TokenStream {
    let parser = value_parser_name(enum_model);
    let name = rust_ident(&enum_model.name);
    quote! {
        fn #parser() -> impl clap::builder::TypedValueParser<Value = typstyle_core::#name> {
            use clap::builder::TypedValueParser as _;
            clap::builder::PossibleValuesParser::new(
                <typstyle_core::#name as typstyle_core::option::OptionEnum>::CHOICES,
            )
            .map(|value| {
                <typstyle_core::#name as typstyle_core::option::OptionEnum>::from_choice(&value)
                    .expect("possible values come from OptionEnum::CHOICES")
            })
        }
    }
}

fn value_parser_name(enum_model: &EnumModel) -> Ident {
    format_ident!("value_parser_{}", snake_case(&enum_model.name))
}

fn format_rust(tokens: TokenStream) -> Result<String> {
    let source = tokens.to_string();
    let file = syn::parse_file(&source).context("generated Rust did not parse")?;
    let body = prettyplease::unparse(&file);
    Ok(format!("{BUILD_HEADER}{}", body.trim_start()))
}

fn doc_attrs(doc: &str) -> TokenStream {
    let lines = doc
        .trim()
        .lines()
        .map(str::trim_end)
        .map(|line| format!(" {line}"))
        .collect::<Vec<_>>();
    quote! {
        #(#[doc = #lines])*
    }
}

fn snake_case(name: &str) -> String {
    let mut out = String::new();
    for (index, character) in name.chars().enumerate() {
        if character.is_ascii_uppercase() {
            if index > 0 {
                out.push('_');
            }
            out.push(character.to_ascii_lowercase());
        } else {
            out.push(character);
        }
    }
    out
}
